/**
 * Generated by orval v7.13.2 🍺 — then HAND-EDITED for D30 (N calendar terms per
 * year, plan §D3). `npm run generate:api` must NOT be re-run: `openapi.json` is stale
 * and covers 4 of 14 modules, so regenerating would delete far more than it restored.
 */
import type { TermType } from './termType';

/**
 * PATCH /settings/semesters/{id} (Dean only). All fields optional.
 *
 * `academic_year_id` and `is_active` are deliberately absent — moving a term between
 * years would silently re-file every enrolment, assessment and snapshot keyed to it,
 * and activation goes through `/activate`, which maintains the one-active invariant.
 *
 * `grade_submission_deadline` is the ONE field where omitted and `null` differ: every
 * other field treats absence as "leave alone", but an explicit `null` REOPENS a closed
 * grade window. The server reads presence, not None-ness, so renaming a term cannot
 * silently reopen it.
 */
export interface SemesterUpdateRequest {
  name?: string;
  term_type?: TermType;
  sequence?: number;
  start_date?: string;
  end_date?: string;
  /**
   * The Lecturer grade-entry cutoff (brief §18 / D30 §D6). NULL means the term never
   * closes — the default, and the safe one: a guessed cutoff would lock lecturers out
   * of a live term. Once it passes, `PUT /assessments/{id}/grades` answers 409
   * `grade_window_closed`.
   */
  grade_submission_deadline?: string | null;
}
